import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class OptionToStringTest {

    private static void setFinalField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);

        // remove final modifier if present
        try {
            Field modifiersField = Field.class.getDeclaredField("modifiers");
            modifiersField.setAccessible(true);
            modifiersField.setInt(field, field.getModifiers() & ~Modifier.FINAL);
        } catch (NoSuchFieldException ignored) {
            // Some JVMs may not allow access to modifiers field; ignore if not available
        }

        field.set(target, value);
    }

    private static void setPrivateIntField(Object target, String fieldName, int value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.setInt(target, value);
    }

    @Test
    public void testToString_DefaultShortOption_NoArgs_NoDeprecated() {
        Option opt = new Option("a", "desc");
        String expected = "[ Option a :: desc :: class java.lang.String ]";
        assertEquals(expected, opt.toString());
    }

    @Test
    public void testToString_WithLongAndHasArg() {
        Option opt = new Option("b", "long", true, "d");
        String expected = "[ Option b long [ARG] :: d :: class java.lang.String ]";
        assertEquals(expected, opt.toString());
    }

    @Test
    public void testToString_WithDeprecatedAndNoLong() throws Exception {
        Option opt = new Option("d", "desc");

        // set deprecated to a non-null value (use package-private DEFAULT)
        Field defaultField = DeprecatedAttributes.class.getDeclaredField("DEFAULT");
        defaultField.setAccessible(true);
        Object defaultDeprecated = defaultField.get(null);

        setFinalField(opt, "deprecated", defaultDeprecated);

        String expected = "[ Option d Deprecated :: desc :: class java.lang.String ]";
        assertEquals(expected, opt.toString());
    }

    @Test
    public void testToString_WithLongDeprecatedAndHasArgs() throws Exception {
        Option opt = new Option("c", "long", false, "x");

        // set deprecated to DEFAULT
        Field defaultField = DeprecatedAttributes.class.getDeclaredField("DEFAULT");
        defaultField.setAccessible(true);
        Object defaultDeprecated = defaultField.get(null);
        setFinalField(opt, "deprecated", defaultDeprecated);

        // set argCount to a value > 1 to trigger hasArgs()
        setPrivateIntField(opt, "argCount", 3);

        String expected = "[ Option c long Deprecated[ARG...] :: x :: class java.lang.String ]";
        assertEquals(expected, opt.toString());
    }
}

